// AST4 · Numbering & series — main 295:64609 · loading 295:64985 · error 295:65262. Read-only.
// Toolbar: "Document number formats in use · BLR shown" + "Read-only reference · generated by the system" (lock).
// Card "Number series" + READ ONLY badge: table Document · Format · Latest number · Resets · Set in; footer note.
//
// Data: GET /admin/settings/companies/:id/numbering — the REAL series (formats from the DB generators).
// Deviations: Figma's formats are illustrative; the real ones are shown (INV <PREFIX>/<n>/<YY-YY>, DC <n>/<PREFIX>/NA/<FY>,
// CN CN/<PREFIX>/<n>/<YY-YY>, the rest <KIND>-<CO>-<nnnnnn>, RFQ global). There is no RMA or supplier-return (SRN) series
// in the backend — GapNote. Company switcher kept so another company's series can be read.
import { IconLock } from '@tabler/icons-react';
import { formatDateTime } from '../../lib/format';
import { Badge, ErrorState, GapNote, Ic, StateCard, errorBody } from '../../ui/desktop';
import { useNumbering } from './api';
import { CardsSkeleton, Note, SCard, SettingsToolbar } from './local';
import { useSettingsCtx } from './SettingsLayout';

const SET_IN: Record<string, string> = {
  INV: 'Company & tax · invoice prefix', DC: 'System · from invoice prefix', CN: 'System · from invoice prefix',
  SO: 'System · assigned at verify', SOUT: 'System · assigned at dispatch', RFQ: 'System · one series for all companies',
};
const RESETS: Record<string, string> = { FISCAL_YEAR: 'Each FY', COMPANY: 'Never', GLOBAL: 'Never' };

export function NumberingTab() {
  const { companyId, setCompanyId, companies, company } = useSettingsCtx();
  const q = useNumbering(companyId || null);
  const code = q.data?.company.entity_code ?? company?.entity_code ?? '…';
  return (
    <>
      <SettingsToolbar
        companies={companies}
        companyId={companyId}
        onCompany={setCompanyId}
      />
      <div className="flex w-full items-center gap-[10px] px-[12px]">
        <p className="min-w-px flex-1 text-[12px] leading-[16px] text-fg-2">{`Document number formats in use · ${code} shown`}</p>
        <Ic icon={IconLock} size={14} className="text-fg-2" />
        <p className="text-[12px] leading-[16px] text-fg-2">Read-only reference · generated by the system</p>
      </div>
      {q.isPending ? <CardsSkeleton titles={['Number series']} /> : q.isError ? (
        <StateCard>
          <ErrorState title="Couldn't load the number series" body={errorBody(q.error)} onRetry={() => q.refetch()} retrying={q.isFetching} />
        </StateCard>
      ) : (
        <SCard title="Number series" right={<Badge tone="neutral" label="READ ONLY" />}>
          <div role="table" className="flex w-full flex-col">
            <div role="row" className="flex w-full items-center gap-[10px] rounded-[14px] bg-subtle px-[10px] py-[8px] text-[12px] font-medium leading-[16px] text-fg-2">
              <span role="columnheader" className="w-[260px] shrink-0">Document</span>
              <span role="columnheader" className="w-[230px] shrink-0">Format</span>
              <span role="columnheader" className="min-w-px flex-1">Latest number</span>
              <span role="columnheader" className="w-[90px] shrink-0">Resets</span>
              <span role="columnheader" className="w-[220px] shrink-0">Set in</span>
            </div>
            {q.data.series.map((s) => (
              <div role="row" key={s.kind} className="flex w-full items-center gap-[10px] border-b border-line px-[10px] py-[10px]">
                <span role="cell" className="w-[260px] shrink-0 text-[14px] font-medium leading-[20px] text-fg">{s.label}</span>
                <span role="cell" className="w-[230px] shrink-0 font-mono text-[13px] leading-[18px] text-fg-2">{s.format}</span>
                <span role="cell" className="flex min-w-px flex-1 flex-col">
                  <span className="font-mono text-[13px] font-medium leading-[18px] text-fg">{s.latest_number ?? 'None issued yet'}</span>
                  <span className="text-[12px] leading-[16px] text-fg-muted">
                    {s.next_number ? `Next ${s.next_number}` : 'Set an invoice prefix first'}
                    {s.last_issued_at ? ` · last ${formatDateTime(s.last_issued_at)}` : ''}
                  </span>
                </span>
                <span role="cell" className="w-[90px] shrink-0 text-[12px] leading-[16px] text-fg-2">{RESETS[s.scope] ?? s.scope}</span>
                <span role="cell" className="w-[220px] shrink-0 text-[12px] leading-[16px] text-fg-2">{SET_IN[s.kind] ?? 'System'}</span>
              </div>
            ))}
          </div>
          <Note>{`Prefixes for invoices and challans are edited in Company & tax. Other series are generated by the system and can't be changed here. <CO> = company code; FY ${q.data.fiscal_year}.`}</Note>
          <GapNote code="NO SERIES">The design lists customer-return (RMA) and supplier-return (SRN) series; the backend has no such documents yet. After-sales cases use ASC.</GapNote>
        </SCard>
      )}
    </>
  );
}
